import{_ as o,r as s,o as p,c as l,e as n,a as i,s as c}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Multisite - October CMS - 4.x","titleTemplate":false,"description":"Learn how to duplicate model records across multiple sites.","frontmatter":{"subtitle":"Learn how to duplicate model records across multiple sites."},"headers":[{"level":2,"title":"Enforcing Synchronization","slug":"enforcing-synchronization","link":"#enforcing-synchronization","children":[]},{"level":2,"title":"Saving Models","slug":"saving-models","link":"#saving-models","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/extend/multisite/multisite.md","filePath":"4.x/extend/multisite/multisite.md"}'),r={name:"4.x/extend/multisite/multisite.md"};function u(d,a,g,k,h,m){const e=s("pre-heading"),t=s("post-heading");return p(),l("div",null,[n(e),a[0]||(a[0]=i("h1",null,"Multisite",-1)),n(t),a[1]||(a[1]=c(`<div class="custom-block aside"><p>For an overview of when to use this trait versus Translatable or MultisiteGroup, see the <a href="./introduction.html">Introduction</a>.</p></div><p>When applying multisite to a model, only records belonging to the active site are available to manage. The active site is attached to the <code>site_id</code> column set on the record. To enable multi-site for a model, apply the <code>October\\Rain\\Database\\Traits\\Multisite</code> trait and define the attributes to propagate across all records using the <code>$propagatable</code> property:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Multisite</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$propagatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_code&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>The <code>$propagatable</code> is required by the multisite trait but can be left as an empty array to disable propagation of any attribute.</p></div><p>To add a <code>site_id</code> column to your table, you may use the <code>integer</code> method from a migration. A <code>site_root_id</code> may also be used to link records together using a root record.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_root_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Now, when a record is created it will be assigned to the active site and switching to a different site will propagate a new record automatically. When updating a record, propagated fields are copied to every record belonging to the root record.</p><h2 id="enforcing-synchronization"><a href="#enforcing-synchronization" class="header-anchor">#</a> Enforcing Synchronization</h2><p>In some cases, all records must exist for every site, such as categories and tags. You may force every record to exist across all sites by setting the <code>$propagatableSync</code> property to true, which is false by default. Once enabled, after a model is saved, it will create the same model for other sites if they do not already exist.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$propagatableSync</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
</code></pre></div><p>When using <a href="./../../cms/multisite/multisite.html">Site Groups</a>, the records will be propagated to all sites within that group. This can be controlled by setting the <code>$propagatableSync</code> property to an array containing configuration options.</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead></table></div><ul><li><strong>sync</strong> - logic to sync specific sites, available options: <code>all</code>, <code>group</code>, <code>locale</code>. Default: <code>group</code></li><li><strong>delete</strong> - delete all linked records when any record is deleted, default: <code>true</code></li><li><strong>except</strong> - provides attribute names that should not be replicated for newly synced records</li></ul><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">protected</span> <span class="token variable">$propagatableSync</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;sync&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;all&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;delete&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;except&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;description&#39;</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="saving-models"><a href="#saving-models" class="header-anchor">#</a> Saving Models</h2><p>Models saved with the multisite trait do not propagate by default. Use the <code>savePropagate</code> method to ensure the propagation rules take effect.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">savePropagate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./introduction.html">Introduction</a></li><li><a href="./translatable.html">Translatable Trait</a></li><li><a href="./multisite-group.html">MultisiteGroup Trait</a></li><li><a href="./../../cms/multisite/multisite.html">Multisite Management</a></li><li><a href="./../services/site.html">Site Service</a></li></ul></div>`,19))])}const v=o(r,[["render",u]]);export{f as __pageData,v as default};
